    pub fn close_profile(self: Arc<Self>) -> Result<(), LogError> {
        let node = Arc::try_unwrap(self).map_err(|_| {
            LogError::Io(std::io::Error::other(
                "profile still has retained Node handles",
            ))
        })?;
        let storage = node.storage.clone();
