# Mutation testing rebuilds once per injected bug; symbols add cost without useful
# diagnostics for these expected failures. Normal dev/test profiles stay unchanged.
[profile.mutants]
inherits = "test"
debug = "none"
incremental = true
//! `mesh-talk-node`: a thin CLI over the `node` API — loads a
//! persistent identity, runs signed-announce LAN discovery and a TCP listener,
//! and drives 1:1 DMs, channels, and file transfers from a line-based REPL
