    env: { ...process.env, CI: "", ...options?.env, MESH_VALIDATION_PROCESS_GROUP_OWNER: undefined } });
  const count = async () => Number(await readFile(path.join(root, "count"), "utf8"));
  return { root, git, run, count, command };
}

