use mesh_talk_core::{discovery::Roster, identity::{account_keystore,keystore},node::Node};
use std::{sync::{Arc,Mutex},path::PathBuf,time::Instant};
#[tokio::main]
async fn main() -> Result<(),Box<dyn std::error::Error>> {
 let args:Vec<String>=std::env::args().collect();
 let dir=PathBuf::from(&args[1]); let password=std::fs::read_to_string(&args[2])?;
 let count:usize=args[3].parse()?;
 std::fs::create_dir_all(&dir)?;
 let identity=keystore::load_or_create(&dir.join("node.keystore"),password.trim())?;
 let account=account_keystore::load_or_create(&dir.join("account.keystore"),password.trim())?;
 let (dm,_)=tokio::sync::mpsc::unbounded_channel();
 let (channel,_)=tokio::sync::mpsc::unbounded_channel();
 let (file,_)=tokio::sync::mpsc::unbounded_channel();
 let node=Node::open_with_account(identity,account,Arc::new(Mutex::new(Roster::default())),dm,channel,file,&dir.join("messages.log"),&dir.join("sent.log"),password.trim())?;
 let own=node.account_id(); let start=Instant::now();
 for i in 0..count {
  node.enqueue_to_account(&own,format!("F03 synthetic retained-history message {i:08}: bounded text payload for startup and history measurement.").as_bytes(),None).await?;
  if (i+1)%1000==0 { println!("accepted={} elapsed_ms={}",i+1,start.elapsed().as_millis()); }
 }
 let query=Instant::now(); let history=node.account_history(&own,50)?;
 assert_eq!(history.len(),50);
 assert!(history.iter().all(|row| row.from_me && row.text.starts_with(b"F03 synthetic retained-history message ")));
 println!("history_rows={} query_us={}",history.len(),query.elapsed().as_micros());
 for iteration in 0..5 {
  let query=Instant::now(); let repeated=node.account_history(&own,50)?;
  assert_eq!(repeated.iter().map(|r|r.id).collect::<Vec<_>>(),history.iter().map(|r|r.id).collect::<Vec<_>>());
  println!("repeat={} query_us={}",iteration,query.elapsed().as_micros());
 }
 node.close_profile()?;
 Ok(())
}
